(
  '4f01ac66-32db-5fc3-afd5-442c652d48f0',
  '1 box leg squat',
  '1 Leg Box Squat',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['This exercise requires a sturdy box or a chair. Simple stand ~6 inches in front of it and balance yourself on one leg. From here, begin squatting down in a smooth controlled motion while keeping your other leg straight out in front of you for balance. Slowly sit down on the box, pause for a 1 count and push back up with the working leg, while never letting your other leg touch the ground.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'jesusd'
),
(
  '2fa1689f-ac2e-5d68-84ca-85bc83eb47f4',
  '1 arm half kneeling lat pulldown',
  '1-Arm Half-Kneeling Lat Pulldown',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Attach a D-Handle to a high pully. And use your lat muscles to pull the weight single handedly.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Expenses7000'
),
(
  'affd7a2f-47b3-5feb-a0e0-abb85c07bfae',
  '1 2 kneeling rotation thoracic',
  '1/2 Kneeling Thoracic Rotation',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['- Begin in a half kneeling position with the', 'leg away from the wall stabilized against the wall', 'with a ball.', '- With both hands directly in front of', 'you, rotate one arm open attempting to reach', 'the wall behind you.', '- Exhale as you rotate, inhale', 'as you return to neutral and repeat.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'amwang4'
),
(
  'c51f7e00-5822-5fa3-9826-823482497762',
  '3 4 sit up',
  '3/4 sit-up',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors', 'erector spinae']::text[],
  ARRAY['Step:1 Settle onto your back with your knees bent and feet planted.', 'Step:2 Set your hands behind your head with your elbows pointing outwards.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
  'https://static.exercisedb.dev/media/2gPfomN.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
