(
  '7ab99d32-8da8-5fb0-bbcd-67444d649c43',
  '4 burpees count',
  '4-count burpees',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Stand straight, feet hip-width apart.', 'Steps:', '1. Squat low and support yourself on the floor with your hands between the knees and in front of your feet, your back straight.', '2. Keeping your hands on the floor, jump your legs backward into high plank position.', '3. Jump your feet forward to return to the squat position.', '4. Repeat.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger'
),
