(
  '912f02be-ef1e-53a0-b7a1-eb1bd2af8ace',
  '45 bend side',
  '45° side bend',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['obliques']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and your arms extended straight down by your sides.', 'Step:2 With your back straight and your core engaged, With control bend your torso to one side, lowering your hand toward your knee.', 'Step:3 Stand or sit tall with the pelvis facing forward.', 'Step:4 Bend sideways through the waist without twisting or letting the hips shift.', 'Step:5 Let the side of the trunk work, do not twist or shift the hips.', 'Step:6 Bring the weight or body back to its starting position without rushing.']::text[],
  'https://static.exercisedb.dev/media/Hy9D21L.gif',
  'gif',
  'exercisedb',
