(
  '610f0637-fed9-5b0f-a804-0c9042a2d664',
  '90 hamstring',
  '90/90 Hamstring',
  'legs',
  'body only',
  'hamstrings',
  ARRAY['calves']::text[],
  ARRAY['Lie on your back, with one leg extended straight out.', 'With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position.', 'Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position.', 'Repeat for 10-20 repetitions, and then switch to the other leg.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/90_90_Hamstring/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
