(
  '522c04b0-0d1e-5ea5-a840-5b91bd84531d',
  '90 hip switches',
  '90/90 Hip Switches',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Sit on the floor with one leg bent at 90 degrees in front of you and the other leg bent at 90 degrees out to the side, so that the rear shin is parallel to the front shin. Keep your torso upright and, if possible, your hands off the floor.', 'Rotate both knees over to the other side so that the legs swap positions and you arrive in the same 90/90 position facing the opposite way. Move slowly and under control, keeping the feet in contact with the floor, and alternate sides for the desired number of repetitions.', 'Mobility drill for internal and external rotation of the hips.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger'
),
(
  '0b913ca0-f523-5fe9-9cd5-ebfc3fb588c3',
  'ab crunch machine',
  'Ab Crunch Machine',
  'core',
  'machine',
  'abdominals',
  '{}'::text[],
  ARRAY['Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.', 'At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.', 'After a second pause, slowly return to the starting position as you breathe in.', 'Repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Crunch_Machine/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '744aac1e-743d-5328-b91b-d9694c74f873',
  'abwheel',
  'Ab Roller',
  'core',
  'other',
  'abdominals',
  ARRAY['shoulders']::text[],
  ARRAY['Hold the Ab Roller with both hands and kneel on the floor.', 'Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Ab_Roller/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'eb823d51-ea1d-5c11-a30e-3d0b53f07952',
  'abdominal crunch',
  'Abdominal Crunch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The **Abdominal Crunch** is a classic core isolation exercise performed on the floor or a mat. Unlike a full sit-up, it involves a smaller range of motion where you only lift your shoulders and upper back off the ground, keeping your lower back pressed firmly against the floor.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'amaesc'
),
