(
  'ac27293d-8f97-5950-b0d0-2c7607bb4df6',
  'abduction standing while',
  'Abduction while standing',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Training a stable stance, predominantly on one leg, is crucial for both sides. On the one hand, it prevents discomfort and, on the other, it establishes a stable foundation. The practitioner assumes the usual standing position and, with a stable upper body, attempts to repeatedly lift the unloaded leg, bend it at the hip and knee, and then lower it again. The movement is also repeated on the other side. The exercise trains the stability of the hip-surrounding muscles.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'tregga'
),
(
  'a914e32f-f690-5e96-8eb7-e1f3ab7c22b0',
  'active hang',
  'Active Hang',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['A static hold from a pull-up bar with straight elbows and actively depressed, stabilized shoulders. Grip a secure bar and let your body hang under control. Keep your elbows straight and gently draw your shoulders down, away from your ears. Maintain this active shoulder position without pulling up, swinging, or repeatedly moving the shoulder blades. Hold for up to 30 seconds. Stop earlier if your grip opens, shoulder control deteriorates, or pain occurs. Record actual seconds, grip, and any assistance used. This is distinct from a relaxed passive dead hang or a moving scapular pull-up.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'nalhilal'
),
(
  '3734156c-267b-5764-9da1-e02ce6f449c5',
  'adductor',
  'Adductor',
  'legs',
  'foam roll',
  'adductors',
  '{}'::text[],
  ARRAY['Lie face down with one leg on a foam roll.', 'Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated.', 'While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '984e392b-4ae1-5b62-88e3-03829e512a34',
  'adductor backs rock',
  'Adductor Rock Backs',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Start on all fours with your hands under your shoulders and your knees under your hips. Extend one leg straight out to the side with the foot flat on the floor and the toes pointing forward.', 'Keep your back flat and slowly push your hips back towards the heel of the kneeling leg until you feel a stretch along the inside of the extended leg. Pause briefly, then return to the starting position. Complete all repetitions on one side before switching legs.', 'Mobility exercise for the adductors and the hips.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger'
),
(
  'e9db5d38-da1f-531a-a7a2-09d0bd38ea92',
  'adductor groin',
  'Adductor/Groin',
  'legs',
  '',
  'adductors',
  '{}'::text[],
  ARRAY['Lie on your back with your feet raised towards the ceiling.', 'Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position.', 'Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so.', 'Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or injury.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Adductor_Groin/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'cdffe203-de29-5888-a404-c07a73e8769d',
  'air bike',
  'Air Bike',
  'core',
  'body only',
  'abdominals',
  '{}'::text[],
  ARRAY['Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position.', 'Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position.', 'Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing in the knee of the left leg. Bring your right elbow close to your left knee by crunching to the side, as you breathe out.', 'Go back to the initial position as you breathe in.', 'Crunch to the opposite side as you cycle your legs and bring closer your left elbow to your right knee and exhale.', 'Continue alternating in this manner until all of the recommended repetitions for each side have been completed.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Air_Bike/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'e4b2686e-061f-5979-9019-d36da5bdf53b',
  'all fours quad stretch',
  'All Fours Quad Stretch',
  'legs',
  'body only',
  'quadriceps',
  ARRAY['quadriceps']::text[],
  ARRAY['Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand.', 'Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors.', 'Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/All_Fours_Quad_Stretch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'ae54f1ef-c49a-5a66-a4bd-51f322883031',
  'all fours squad stretch',
  'all fours squad stretch',
  'legs',
  'bodyweight',
  'quadriceps',
  ARRAY['hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Get onto hands and knees with your hands directly under your shoulders and your knees directly under your hips.', 'Step:2 Reach one leg straight back, keeping your knee bent and your foot flexed.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/LzX8YEz.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
