(
  '5f0695a0-710a-5601-9e78-e9ac6ac5ef4b',
  'alternate curl hammer',
  'Alternate Hammer Curl',
  'biceps',
  'dumbbell',
  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso.', 'The palms of the hands should be facing your torso. This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbells back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Hammer_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '78f519dd-da5f-53f0-aa15-15a819f92f7b',
  'alternate heel touchers',
  'alternate heel touchers',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['obliques']::text[],
  ARRAY['Step:1 Settle onto your back with your knees bent and feet planted.', 'Step:2 Reach your arms straight out to the sides, parallel to the ground.', 'Step:3 Stand or sit tall with the pelvis facing forward.', 'Step:4 Bend sideways through the waist without twisting or letting the hips shift.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Bring the weight or body back to its starting position without rushing, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/qaZVsGk.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '75f88b7e-b57b-5459-8dd5-6c647811f71c',
  'alternate curl dumbbell incline',
  'Alternate Incline Dumbbell Curl',
  'biceps',
  'dumbbell',
  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position.', 'While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the biceps. Tip: Only the forearms should move.', 'Slowly begin to bring the dumbbell back to starting position as your breathe in.', 'Repeat the movement with the left hand. This equals one repetition.', 'Continue alternating in this manner for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Incline_Dumbbell_Curl/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '7942a915-3507-523b-9b1c-bb3c0acb43c9',
  'alternate lateral pulldown',
  'alternate lateral pulldown',
  'back',
  'cable',
  'latissimus dorsi',
  ARRAY['biceps', 'rhomboids']::text[],
  ARRAY['Step:1 Take a seat on the cable machine with your back straight and feet planted.', 'Step:2 Hold the handles with palms facing down, just beyond shoulder width.', 'Step:3 Sit tall and set the shoulders before drawing the handle down.', 'Step:4 Pull the handle down by driving your elbows toward your ribs, keep your torso steady.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/4IKbhHV.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'd128550a-6699-5dc6-a819-401e434f0d44',
  'alternate bound diagonal leg',
  'Alternate Leg Diagonal Bound',
  'legs',
  '',
  'quadriceps',
  ARRAY['abductors', 'adductors', 'calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Assume a comfortable stance with one foot slightly in front of the other.', 'Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound.', 'It may help to use a line on the ground to guage distance from side to side.', 'Repeat the sequence with the other leg.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternate_Leg_Diagonal_Bound/0.jpg',
  'image',
