(
  '46fd88dd-06d9-547e-a5b8-59ee7426f839',
  'alternate bicep curl',
  'Alternating bicep curls',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Start standing up with dumbbells in each hand, your back straight and feet hip-width apart. Your arms should be relaxed, pointing down. Your knees should be slightly bent, your abs contracted, and your shoulders down.', 'Steps:', '1. Bend one arm at the elbow, bringing the dumbbell up to your shoulder. Your upper arm should remain motionless during this movement.', '2. Bring the dumbbell back down until your arm is in its original relaxed position.', '3. Repeat, switching arms.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger'
),
(
  'a1796bf0-ae49-5df8-a20f-d9b1c9b6d499',
  'alternate deltoid raise',
  'Alternating Deltoid Raise',
  'shoulders',
  'dumbbell',
  'shoulders',
  '{}'::text[],
  ARRAY['In a standing position, hold a pair of dumbbells at your side.', 'Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating.', 'Return the weights to your side.', 'On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height.', 'Return the weights to the starting position and continue alternating to the front and side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Deltoid_Raise/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
