(
  'f54293f7-45f9-5ef4-8aa5-c8c7e40b4302',
  'alternate clean hang',
  'Alternating Hang Clean',
  'legs',
  'kettlebells',
  'hamstrings',
  ARRAY['biceps', 'calves', 'forearms', 'glutes', 'lower back', 'traps']::text[],
  ARRAY['Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead.', 'Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so.', 'Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Hang_Clean/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
