),
(
  '6bf78394-7e1d-5455-9d41-7877dbb39fc3',
  'alternate cable high row',
  'Alternating High Cable Row',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Start', 'by putting the attachment in a high position on the cable station and step back about 1m from the attachment. Grab', 'the cable pulley handle in your left hand at about head height with your elbow slightly bent. Step back with your left foot.', '2. Pull', 'your elbow joint in toward the torso twisting slightly and perform a', 'single-arm row. Engage the lats as you twist.', '3. Return', 'to the starting position with cable pulley and left foot and grab the cable pulley handle in the right', 'hand. Repeat this motion on the opposite side with your right foot stepped back.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Moffi'
),
(
  '1718262d-2c6c-526b-9f5e-25faff7e61aa',
  'alternate renegade row',
  'Alternating Renegade Row',
  'back',
  'kettlebells',
  'middle back',
  ARRAY['abdominals', 'biceps', 'chest', 'lats', 'triceps']::text[],
  ARRAY['Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support.', 'Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side.', 'Then lower the kettlebell to the floor and begin the kettlebell in the opposite hand. Repeat for several reps.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Alternating_Renegade_Row/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
