  ARRAY['Step:1 Take a seat on a bench with your back straight and feet planted.', 'Step:2 Take a dumbbell in each hand, palms facing inwards, and raise them to shoulder height.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weight or handles away while keeping your trunk braced.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Lower the weight to its starting height under control before pressing again, switch sides when the set calls for it.']::text[],
