  'calves',
  ARRAY['ankle stabilizers']::text[],
  ARRAY['Step:1 Take a seat on the ground with your legs extended in front of you.', 'Step:2 Before moving, lift one leg off the ground and rotate your ankle in a circular motion.', 'Step:3 Relax the limb above the joint you are circling.', 'Step:4 Circle the joint slowly in one direction, then reverse the circle without forcing the range.', 'Step:5 Keep the rest of the limb still while the joint traces each circle.', 'Step:6 Switch to the other side after completing both directions.']::text[],
