(
  'c65ca05e-6bd9-583d-884d-485d7f4ca216',
  'archer pullup',
  'Archer Pull-Up',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['biceps', 'forearms']::text[],
  ARRAY['Step:1 Begin by hanging from a pull-up bar with palms facing down, just beyond shoulder width.', 'Step:2 Brace your trunk and pull your shoulder blades down and back.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
