  'bodyweight',
  'pectorals',
  ARRAY['triceps', 'deltoids', 'core']::text[],
  ARRAY['Step:1 Begin in a push-up position with your hands just beyond shoulder width.', 'Step:2 Reach one arm straight out to the side, parallel to the ground.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Shift toward one hand and bend that elbow while the other arm straightens to the side.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
