(
  'f8a8b58a-6c09-5734-971c-94444f453f6d',
  'arm i raise t y',
  'Arm Raises (T/Y/I)',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Stand upright with feet hip-width apart, core engaged, and arms relaxed at your sides. From this position, perform three different arm raises to target the shoulders and upper back:', '* **T Raise:** Lift your arms straight out to the sides until they are parallel to the floor, forming a “T” shape.', '* **Y Raise:** Lift your arms upward at about a 45° angle from your body to form a “Y” shape.', '* **I Raise:** Raise your arms straight overhead, close together, forming an “I” shape.', 'Maintain a neutral spine, avoid arching your lower back, and move slowly with control. Focus on squeezing your shoulder blades together and keeping your shoulders down away from your ears.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'WiNNiE'
),
