  'bodyweight',
  'abdominals',
  ARRAY['deltoids', 'back']::text[],
  ARRAY['Step:1 Suspend yourself from a pull-up bar with your arms straight and your knees bent at a 90-degree angle.', 'Step:2 Brace your trunk and lift your knees toward your chest, bringing them as close to your elbows as possible.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Step:5 Slow the legs before they pull the lower back out of position.', 'Step:6 Lower the legs slowly without swinging or losing your trunk position.']::text[],
  'https://static.exercisedb.dev/media/uWpxD4v.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
