  'glutes',
  ARRAY['hamstrings', 'quadriceps', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and arms extended to the sides.', 'Step:2 With your legs straight, bend forward at the waist and reach down toward your toes with your right hand.', 'Step:3 Soften the knees and let the hips start the fold.', 'Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Step:5 Keep the movement controlled throughout the range.', 'Step:6 Hold briefly at a comfortable depth, then rise by extending the hips.']::text[],
