(
  '2917874b-3ada-5f31-9c7b-121ecee16d52',
  'atlas stone trainer',
  'Atlas Stone Trainer',
  'back',
  'other',
  'lower back',
  ARRAY['biceps', 'forearms', 'glutes', 'hamstrings', 'quadriceps']::text[],
  ARRAY['This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe.', 'Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips.', 'Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest.', 'Finish the movement by extending through your hips and knees to raise the weight as high as possible. The weight can be returned to the lap or to the ground for successive repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Atlas_Stone_Trainer/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'd79ca39b-0310-52fe-96a4-db98ca912eba',
  'atlas stones',
  'Atlas Stones',
  'back',
  'other',
  'lower back',
  ARRAY['abdominals', 'adductors', 'biceps', 'calves', 'forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[],
  ARRAY['Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold.', 'Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground.', 'As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs.', 'Sit low, getting the stone high onto your chest as you change your grip to reach over the stone. Stand, driving through with your hips. Close distance to the loading platform, and lean back, extending the hips to get the stone as high as possible.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Atlas_Stones/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'ab9dc7d3-2259-5bd3-86b4-67da55673078',
  'australian pullup',
  'Australian pull-ups',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Lie down under a high bar or suspension bar, positioned at an appropriate height.', '2. Position yourself on your back under the bar, gripping the bar with a supinated grip (palms facing you).', '3. Adjust your position so that your body is aligned straight from head to toe. Arms should be fully extended, shoulders stabilized, and legs aligned with the rest of the body.', '4. Bend your elbows and pull your chest towards the bar, contracting your back muscles. Imagine you''re trying to bring your shoulder blades together.', '5. Hold the contraction at the top of the movement for a moment to maximize muscle activation.', '6. Slowly return to the starting position, extending your elbows.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'PaukOne'
),
