(
  '1a4d882e-42bd-5781-9833-2bf007e348f0',
  'axle deadlift',
  'Axle Deadlift',
  'back',
  'other',
  'lower back',
  ARRAY['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[],
  ARRAY['Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip.', 'With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward.', 'After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Axle_Deadlift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '5fb3929f-cf16-5c57-8951-20dec5a89585',
  'back forth step',
  'back and forth step',
  'cardio',
  'bodyweight',
  'cardiovascular system',
  ARRAY['quadriceps', 'hamstrings', 'glutes', 'calves']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width.', 'Step:2 Move forward with your right foot, bending your knee and lowering your body into a lunge position.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Step:5 Keep the pattern repeatable as speed increases.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
  'https://static.exercisedb.dev/media/fNGumX0.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '16c2672f-9196-5101-999a-a96cd14ee955',
  'back bridge',
  'Back bridge',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Lie on the floor with your back resting on the floor and your legs bent, feet flat on the floor, leaving about 20 cm between your feet and your buttocks. Your hands remain flat on the floor, pressed against your ears, with your fingers pointing toward your toes. Your elbows are bent and pointing toward the ceiling. This is the starting position. Now push your hips as high as you can, raising your body off the floor, and continue pushing through your hands, extending your elbows and knees, until your back is fully arched (lumbar bridge). Your head also comes off the floor and should be level with your elbows, looking back. This is the final position. The descent should be slow and controlled. Your spine should be in a convex curve. It''s not good to lift your back off the floor, it should remain straight. It should be well rounded. You''ll also notice a feeling of increased oxygenation in your back. After lifting off the floor, your hips should be very high, even above the level of your head. Your arms and legs should remain straight. It seems easy, but it requires a good level of flexibility. Breathing should be deep. This posture stretches the rib cage and puts pressure on the diaphragm. If the posture is performed correctly, breathing will be perfect. Never hold your breath during the exercise.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'cynomops'
),
(
