  'back extension stabilityball',
  'back extension on exercise ball',
  'back',
  'stability ball',
  'erector spinae',
  ARRAY['glutes', 'hamstrings']::text[],
  ARRAY['Step:1 Set the stability ball on the ground and Position yourself face down on top of it, with your hips resting on the ball and your feet against a wall or other stable surface.', 'Step:2 Set your hands behind your head or crossed over your chest.', 'Step:3 Secure the hips and feet on the support before lifting.', 'Step:4 Raise your torso or legs until they line up with your body, without arching sharply at the lower back.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Return along the same path at a controlled pace.']::text[],
  'https://static.exercisedb.dev/media/qLpO4vV.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
