(
  'a20c19b1-aa4c-5b5c-a8e9-281da89d00d7',
  'ball slams',
  'Ball Slams',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Stand with your feet about shoulder-width apart, your knees and hips slightly bent, holding the ball in both hands at chest height. Engage your core, and keep a good posture.', '2. Extend your knees and drive your hips forward while simultaneously lifting the ball. Aim for being as tall as possible, the ball overhead, arms up, hips slightly forward, and on your toes from the force of your drive.', '3. Use your core and arms to slam the medicine ball straight down between your feet with as much force as possible. Press your hips back and bend your knees to further power the slam. Exhale as you slam the ball down.', '4. Squat down to pick up the ball from the floor, then immediately move into the next slam by repeating the movement. Repeat for reps or time.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'flanny'
),
