  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Step:1 Stand and set your feet about shoulder width and hold the band with palms facing up.', 'Step:2 Hold your elbows near your sides and With control curl one arm up toward your shoulder, squeezing your biceps at the top.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still, switch sides when the set calls for it.']::text[],
  'https://static.exercisedb.dev/media/3omWx6P.gif',
