  ARRAY['Step:1 Connect the band to a pull-up bar or sturdy anchor point.', 'Step:2 Step onto the band and grip the bar with your palms turned away from you, hands just beyond shoulder width.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Control the band on the way back instead of letting it snap you into position.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
