  ARRAY['Step:1 Connect the band to a sturdy anchor point at chest height.', 'Step:2 Stand and set your side facing the anchor point and grab the band with one hand.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weights up while turning the palms inward, reverse the turn as you lower.', 'Step:5 Keep both shoulders level and resist turning toward the working arm.', 'Step:6 Lower the weight to its starting height under control before pressing again, switch sides when the set calls for it.']::text[],
