  '{}'::text[],
  ARRAY['A banded walking drill for the glutes and hip stabilisers. Place a mini band around both thighs just above the knees, or around the ankles for a harder version. Stand with feet hip-width apart so the band is under tension, then sink into a quarter-squat with the chest up. Walk forward with small diagonal steps, pushing each leg out against the band and keeping the knees tracking over the toes rather than letting them fall inward. Walk forward for the prescribed number of steps, then walk backward to return, keeping the band under tension throughout.']::text[],
