(
  '4dcf3e45-6ed6-5ff1-ae2f-5980e0b1d010',
  'ab barbell rollout',
  'Barbell Ab Rollout',
  'core',
  'barbell',
  'abdominals',
  ARRAY['lower back', 'shoulders']::text[],
  ARRAY['For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position.', 'While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all times. Also your arms should be staying perpendicular to the floor throughout the movement. If you don''t, you will work out your shoulders and back more than the abs.', 'After a second contraction at the top, start to roll the barbell back forward to the starting position slowly as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '2fdd7af4-98a0-5ac1-8cef-262f961a2feb',
  'ab barbell knees rollout',
  'Barbell Ab Rollout - On Knees',
  'core',
  'barbell',
  'abdominals',
  ARRAY['lower back', 'shoulders']::text[],
  ARRAY['Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor.', 'Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position.', 'Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement.', 'After a second pause at the stretched position, start pulling yourself back to the starting position as you breathe out. Tip: Go slowly and keep your abs tight at all times.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Barbell_Ab_Rollout_-_On_Knees/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
