  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Step:1 Stand tall with your feet about shoulder width and hold a barbell in each hand, palms facing forward.', 'Step:2 Let the elbows do the moving while the upper arms stay put and Breathe out and curl the weights while contracting your biceps.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still, switch sides when the set calls for it.']::text[],
