  ARRAY['Step:1 Plant both feet while seated on a bench, hold a barbell with palms facing up, hands about shoulder width.', 'Step:2 Set your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Step:5 Keep the torso quiet and let the elbow bend lift the weight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
