  ARRAY['Step:1 Stand and set your feet about shoulder width and knees soft.', 'Step:2 Keep one end of the rope in each hand, with your palms facing each other.', 'Step:3 Start at a pace that lets the feet and arms move in sync.', 'Step:4 Move at a repeatable pace, keeping the motion smooth and your breathing steady.', 'Step:5 Keep the pattern repeatable as speed increases.', 'Step:6 Keep the rhythm for the planned interval, slowing if your form starts to slip.']::text[],
