  'bench bent dip knees',
  'bench dip (knees bent)',
  'triceps',
  'bodyweight',
  'triceps',
  ARRAY['pectorals', 'deltoids']::text[],
  ARRAY['Step:1 Take a seat on the edge of a bench or chair with your hands gripping the edge next to your hips.', 'Step:2 Move your butt off the bench and straighten your legs in front of you, keeping your heels on the ground.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Choose a depth that lets the shoulders stay comfortable.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep.']::text[],
