(
  '60bed6c1-1157-5228-9cb5-5d164ececc59',
  'bench dips',
  'Bench Dips',
  'triceps',
  'body only',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position.', 'Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller than 90 degrees between the upper arm and the forearm. Tip: Keep the elbows as close as possible throughout the movement. Forearms should always be pointing down.', 'Using your triceps to bring your torso up again, lift yourself back to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Dips/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'cb83c8d1-03de-53d7-9c17-6901c06c74ad',
  'bench dips floor',
  'Bench Dips On Floor HD',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Triceps dips on floor are a compound exercise as they worked multiple muscle groups simultaneously. Although this bodyweight exercise mainly targets the triceps, it also hits your chest and front of your shoulder.', 'Triceps dips on floor are one of the most effective exercises to increase arm strength and also build lean muscle in your upper arms.', 'Triceps dips on floor are a closed kinetic chain exercise and express that you do the movements around a fixed point. It increases compression force on your joints thereby improving stability.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'hektkaso'
),
(
  '256303e8-8cfd-5fab-820b-a85e80fba707',
  'bench extension hip',
  'bench hip extension',
  'legs',
  'bodyweight',
  'glutes',
  ARRAY['hamstrings']::text[],
  ARRAY['Step:1 Take a seat on a bench with your back against the bench and your feet planted.', 'Step:2 Set your hands on the bench for support.', 'Step:3 Plant the feet and keep the ribs from flaring as the hips prepare to rise.', 'Step:4 Press through the feet and lift your hips until your torso and thighs line up.', 'Step:5 Stop when the hips line up with the torso, do not arch higher through the lower back.', 'Step:6 Lower the hips steadily and keep the feet planted for the next lift.']::text[],
