(
  '89f5183a-92e5-5f0d-8991-cad08edc148c',
  'bench press',
  'Bench Press',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Lay down on a bench, the bar should be directly above your eyes, the knees are somewhat angled and the feet are firmly on the floor. Concentrate, breath deeply and grab the bar more than shoulder wide. Bring it slowly down till it briefly touches your chest at the height of your nipples. Push the bar up.', 'If you train with a high weight it is advisable to have a *spotter* that can help you up if you can''t lift the weight on your own.', 'With the width of the grip you can also control which part of the chest is trained more:', '* wide grip: outer chest muscles', '* narrow grip: inner chest muscles and triceps']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'sistab2'
),
(
  '2481e3cb-ed2a-571d-aa13-9fa719b64f82',
  'bench powerlifting press',
  'Bench Press - Powerlifting',
  'triceps',
  'barbell',
  'triceps',
  ARRAY['chest', 'forearms', 'lats', 'shoulders']::text[],
  ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to your lower chest or upper stomach. The bar, wrist, and elbow should stay in line at all times.', 'Pause when the barbell touches your torso, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_Powerlifting/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '2a9c00ac-19c5-586d-84f7-3d347c7c8d99',
  'bands bench press',
  'Bench Press - With Bands',
  'chest',
  'bands',
  'chest',
  ARRAY['shoulders', 'triceps']::text[],
  ARRAY['Using a flat bench secure a band under the leg of the bench that is nearest to your head.', 'Once the band is secure, grab it by both handles and lie down on the bench.', 'Extend your arms so that you are holding the band handles in front of you at shoulder width.', 'Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.', 'Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at all times.', 'As you breathe out, bring the handles up using your pectoral muscles. Lock your arms in the contracted position, squeeze your chest, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.', 'Repeat the movement for the prescribed amount of repetitions of your training program.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bench_Press_-_With_Bands/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
