  'bench closegrip press',
  'Bench Press Narrow Grip',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['- **Setup:** Lie flat on the bench and grip the bar at shoulder-width (closer than a standard bench press).', '- **Descent:** Lower the bar with control to your lower chest.', '- **Form:** Keep your elbows tucked in tight against your torso—do not let them flare out.', '- **Ascent:** Press the bar straight back up, squeezing your triceps at the top.']::text[],
