  'bench pullup',
  'bench pull-ups',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['biceps', 'forearms']::text[],
  ARRAY['Step:1 Set yourself under a bar or a sturdy horizontal surface that is at chest height.', 'Step:2 Take hold of the bar or surface with palms facing down, just beyond shoulder width.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
