(
  '53634cc7-f105-5526-8e19-89d70bd6f688',
  'bench sprint',
  'Bench Sprint',
  'legs',
  'other',
  'quadriceps',
  ARRAY['calves', 'glutes', 'hamstrings']::text[],
  ARRAY['Stand on the ground with one foot resting on a bench or box with your heel close to the edge.', 'Push off with your foot on top of the bench, extending through the hip and knee.', 'Land with the opposite foot on top of the box, returning your other foot back to the start position.', 'Continue alternating from one foot to another to complete the set.']::text[],
