(
  '4ea6eab8-5b12-5264-b9df-08acac3b73a4',
  'benchpress dumbbell',
  'Benchpress Dumbbells',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Setup and Starting Position: Sit at the end of a flat bench with a dumbbell resting vertically against each thigh. Carefully lean back while driving the dumbbells toward your chest with your knees.', '2. The “Leg Drive” and Posture: Plant your feet firmly on the floor. Retract your shoulder blades (press them together against the bench) and maintain a slight natural lumbar curve.', '3. Starting Position: Push the dumbbells toward the ceiling. Your wrists should be aligned with your elbows. Rotate the dumbbells slightly inward (about 45 degrees) so that your elbows do not splay out too far to the sides, thereby protecting your shoulders.', '4. Eccentric Phase (Lowering): Lower the dumbbells in a controlled manner toward the sides of your chest. Your elbows should lower at an angle of about 45–60 degrees relative to your body. Feel the stretch in the lower part of your chest.', '5. Concentric Phase (Lift): Push the weight upward in a slight arc (toward the center), without letting the dumbbells collide at the top or fully locking out your elbows to maintain muscle tension. Exhale as you lift.', 'Translated with DeepL.com (free version)']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger.de'
),
