  'bodyweight',
  'glutes',
  ARRAY['obliques', 'hip flexors']::text[],
  ARRAY['Step:1 Settle onto your back with your knees bent and feet planted.', 'Step:2 Reach your arms out to the sides, perpendicular to your body.', 'Step:3 Set the pelvis and make the turn through the rib cage.', 'Step:4 Turn through the torso while the hips and lower body stay as steady as the setup allows.', 'Step:5 Keep the turn smooth instead of throwing the arms across the body.', 'Step:6 Return through center before turning to the other side.']::text[],
