(
  'df2f32f7-9f57-5cbf-b97b-ce1d61540b2d',
  'bench bentover delt dumbbell head raise rear',
  'Bent Over Dumbbell Rear Delt Raise With Head On Bench',
  'shoulders',
  'dumbbell',
  'shoulders',
  '{}'::text[],
  ARRAY['Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you.', 'While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position.', 'Keeping your torso forward and stationary, and the arms straight with a slight bend at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. Caution: avoid swinging the torso or bringing the arms back as opposed to the side.', 'After a one second contraction at the top, slowly lower the dumbbells back to the starting position.', 'Repeat the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg',
