  'Unlicense',
  null
),
(
  '9d5ac9f7-c4d8-5bbf-aac4-cea612ea739c',
  'arms bentover dumbbell row',
  'Bent Over Dumbbell Rows (Two Arms)',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**How to Perform It**', '- Hold a dumbbell in each hand with a neutral or overhand grip.', '- Hinge at the hips, pushing your glutes back, until your torso is roughly 45–75 degrees to the floor. Keep a slight bend in your knees.', '- Let the dumbbells hang directly below your shoulders with arms fully extended.', '- Keep your back flat, chest up, and core braced — avoid rounding your spine.', '- Pull the dumbbells up toward your ribcage/hips, driving your elbows back and squeezing your shoulder blades together at the top.', '- Pause briefly at the top of the movement.', '- Lower the dumbbells back down under control to the starting position.', '- Repeat for the desired number of repetitions.', '**Key Coaching Cues**', '- Hinge from the hips, not the lower back', '- Keep the spine neutral throughout — no rounding', '- Lead with the elbows, not the hands', '- Avoid using momentum or jerking the weight up', '- Control the eccentric (lowering) phase rather than letting the weights drop']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'karthikrrk'
),
(
  '5847df9e-3442-5bd8-8c23-5fe1bbcf84d2',
  'bentover lateral low pulley side',
  'Bent Over Low-Pulley Side Lateral',
  'shoulders',
  'cable',
  'shoulders',
  ARRAY['lower back', 'middle back', 'traps']::text[],
  ARRAY['Select a weight and hold the handle of the low pulley with your right hand.', 'Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position.', 'Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. Breathe out as you perform this step.', 'Slowly lower the weight back to the starting position as you breathe in.', 'Repeat for the recommended amount of repetitions and repeat the movement with the other arm.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_Low-Pulley_Side_Lateral/0.jpg',
  'image',
