),
(
  'b82aeea3-8760-599b-a4fd-d757bf5c9d25',
  'bar bentover long row singlearm',
  'Bent Over One-Arm Long Bar Row',
  'back',
  'barbell',
  'middle back',
  ARRAY['biceps', 'lats', 'lower back', 'traps']::text[],
  ARRAY['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls, or put a heavy object on the ground so the barbell cannot slide backward.', 'Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.', 'Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.', 'Pull the bar straight up with your elbow in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Do not allow for any swinging of the torso. Only the arm should move.', 'Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).', 'Repeat for the recommended amount of repetitions and switch arms.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Bent_Over_One-Arm_Long_Bar_Row/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '0d1ecc3d-52a2-54c4-af83-0aa7f3b432f1',
  'bentover external rotation row',
  'Bent over row to external rotation',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**Starting position:**', 'Stand behind a chair or in front of a table. Bend at the waist to put your forehead on the chair''s headrest or table, keeping your back straight. Your arms should be hanging straight down, pointed at the floor.', '**Steps:**', '1. Bring your elbows up to shoulder height. Your forearms should be pointing down, perpendicular to your biceps. Your biceps should be at the same height as your back and perpendicular to your spine.', '2. Hold for a bit.', '3. Rotate at your elbows to bring your hands as far up as you can.', '4. Hold for a bit.', '5. Rotate at your elbows back to the previous position.', '6. Bring your arms down to the original position.', '7. Repeat.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'tinman'
),
(
  '2f004d98-be1a-5140-8852-5059577dd920',
  'bentover rowing',
  'Bent Over Rowing',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.', '2. Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.', '3. Then inhale and slowly lower the barbell back to the starting position.', '4. Repeat for the recommended amount of repetitions.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger.de'
),
(
  'd371a3c4-9abe-585e-8d19-7755b48a1cbf',
  'bentover reverse rowing',
  'Bent Over Rowing Reverse',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The same as *regular* rowing, but holding a reversed grip (your palms pointing forwards):', 'Grab the barbell with a wide grIp (slightly more than shoulder wide) and lean forward. Your upper body is not quite parallel to the floor, but forms a slight angle. The chest''s out during the whole exercise.', 'Pull now the barbell with a fast movement towards your belly button, not further up. Go slowly down to the initial position. Don''t swing with your body and keep your arms next to your body.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'wger.de'
),
(
  'a4b63940-2a33-5a96-a1c5-9a65e8f4fba6',
  'arm bar bentover long row',
  'Bent Over Two-Arm Long Bar Row',
  'back',
  'barbell',
  'middle back',
  ARRAY['biceps', 'lats']::text[],
  ARRAY['Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls, or put a heavy object on the ground so the barbell cannot slide backward.', 'Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent.', 'Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.', 'Pull the bar straight up with your elbows in (to maximize back stimulation) until the plates touch your lower chest. Squeeze the back muscles as you lift the weight up and hold for a second at the top of the movement. Breathe out as you lift the weight. Tip: Use a stirrup or double handle cable attachment by hooking it under the end of the bar.', 'Slowly lower the bar to the starting position getting a nice stretch on the lats. Tip: Do not let the plates touch the floor. To ensure the best range of motion, I recommend using small plates (25-lb ones) as opposed to larger plates (like 35-45lb ones).', 'Repeat for the recommended amount of repetitions.']::text[],
