  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Step:1 Take a seat on a bench with your legs spread apart and your feet planted.', 'Step:2 Take a dumbbell in one hand and place your elbow on the inside of your thigh, just above the knee.', 'Step:3 Set the shoulders and upper arms before bending the elbows.', 'Step:4 Bend your elbows to bring the weight toward your shoulders without swinging your torso.', 'Step:5 Keep the torso quiet and let the elbow bend lift the weight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
