  'bodyweight',
  'biceps',
  ARRAY['forearms', 'deltoids']::text[],
  ARRAY['Step:1 Suspend yourself from a pull-up bar with your palms facing toward you and your hands about shoulder width.', 'Step:2 Brace your trunk and pull yourself up toward the bar, focusing on using your biceps to lift your body.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
