  'bicycle crunch',
  'Bicycle Crunch',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Settle onto your back with your hands placed behind your head.', 'Step:2 Before moving, lift your legs off the ground and bend your knees at a 90-degree angle.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Bring one elbow toward the opposite knee as the other leg extends, switch sides in a steady rhythm.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
