(
  '2a300ad6-afbc-503e-8ac3-4aab176cb5fb',
  'bird dog',
  'Bird Dog',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The Bird Dog is a core stability exercise that enhances balance, coordination, and spinal alignment. It’s a low-impact movement ideal for strengthening the posterior chain and improving overall functional control.', '1. Begin on all fours with hands under shoulders and knees under hips, keeping your spine neutral.', '2. Extend your right arm forward and left leg backward simultaneously, keeping hips square.', '3. Pause briefly at full extension while engaging your core and glutes.', '4. Return to the starting position and repeat on the opposite side']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Settebello'
),
(
  '67d65d1b-337e-5b6f-8044-c00a64a77bae',
  'bizeps curl trifecta',
  'Bizeps Curls Trifecta',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['This exercise is a mixture of three different curls: the Supinated Cross Body Curl, the Pronated Cross Body Curl and the No Money Curl. You', 'alternate between three curl variations that each accomplish different goals,', 'and you’ll keep the set going beyond the usual 8-12 rep range which gives', 'us that intensity.', '1. For the Supinated Cross Body', 'Curl, supinate the forearm with palms facing toward the ceiling and', 'forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.', '2. For the Pronated Cross Body', 'Curl, pronate the forearm with palms facing toward the floor (pronated', 'grip or overhand grip) and forearms coming across the body. Lift the inner-facing weight of the dumbbell towards your shoulder.', '3. For the No Money Curl, you’ll', 'curl the dumbbell as you outwardly rotate the shoulder. Lift the inner-facing weight of the dumbbell towards your outer side of the shoulder.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Moffi'
),
(
  '7c6cce3d-49c1-5bec-947c-89f8fd5fc19f',
  'black knee slides widow',
  'Black Widow Knee Slides',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['In', 'this bottom-up rotation exercise movement, you’ll cross your knee over and', 'drive it into that opposite elbow. Start in high plank position (or tabletop', 'position) with hands directly beneath your shoulders. Lift the left knee toward', 'the right arm and slide it up the forearm to get more of that posterior pelvic', 'tilt and engagement of the abdominal muscles. Then do the opposite side,', 'bringing your right knee toward your left hand.']::text[],
  null,
  null,
