(
  '1f87cbd1-b087-53bc-94b7-6f5ec2af00e1',
  'board press',
  'Board Press',
  'triceps',
  'barbell',
  'triceps',
  ARRAY['chest', 'forearms', 'lats', 'shoulders']::text[],
  ARRAY['Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt.', 'Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement.', 'You can take a standard bench grip, or shoulder width to focus on the triceps. Pull the bar out of the rack without protracting your shoulders. The bar, wrist, and elbow should stay in line at all times. Focus on squeezing the bar and trying to pull it apart.', 'Lower the bar to the boards, and then drive the bar up with as much force as possible. The elbows should be tucked in until lockout.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Board_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '8cd9a86d-9721-51cf-9cb1-0498a2709d5c',
  'bobbing drill exhale',
  'Bobbing Exhale Drill',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Stand in chest-deep water. Take a breath, submerge your face fully, and exhale slowly and completely through your nose and/or mouth the whole time you''re underwater — a gentle humming sound can help keep the exhale steady and controlled. Once you''re empty of air, lift your head, take a fresh breath, and go back under. Repeat continuously. The goal is training your body that all your exhaling happens underwater, so all you need to do at the surface is inhale.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Imported from swim plan'
),
