  ARRAY['pectorals', 'deltoids']::text[],
  ARRAY['Step:1 Begin by placing your hands on a raised surface, such as a bench or parallel bars, with your palms facing down and fingers pointing forward.', 'Step:2 Reach your legs out in front of you, keeping your heels on the ground and your body straight.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Choose a depth that lets the shoulders stay comfortable.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep.']::text[],
