  'abdominals',
  ARRAY['obliques', 'deltoids']::text[],
  ARRAY['Step:1 Begin by lying on your side with your legs extended and stacked on top of each other.', 'Step:2 Set your forearm on the ground directly below your shoulder, with your elbow bent at a 90-degree angle.', 'Step:3 Brace the abdomen and find a position you can maintain without holding your breath.', 'Step:4 Brace your midsection and hold the position while breathing normally.', 'Step:5 Keep breathing steadily as you maintain the same body line.', 'Step:6 Keep the shape for the planned time, then come out of it with control.']::text[],
