  'box down jump singleleg stabilization',
  'Box Jump Down With Single-Leg Stabilization',
  'legs',
  'bodyweight',
  'calves',
  ARRAY['quadriceps', 'hamstrings', 'glutes']::text[],
  ARRAY['Step:1 Take your place in front of a box or platform with your feet about shoulder width.', 'Step:2 Before moving, bend your knees and jump onto the box, landing softly with one foot on the box and the other foot hanging off the edge.', 'Step:3 Bend the hips and knees slightly to load the jump.', 'Step:4 Load the legs with a small bend, then drive through the floor and land softly.', 'Step:5 Keep the pelvis level as the supporting leg does the work.', 'Step:6 Absorb the landing through the hips and knees before repeating, switch sides when the set calls for it.']::text[],
