(
  '15acb68a-ff69-5922-b0f4-e3b870092eff',
  'box skip',
  'Box Skip',
  'legs',
  'other',
  'hamstrings',
  ARRAY['abductors', 'adductors', 'calves', 'glutes', 'quadriceps']::text[],
  ARRAY['You will need several boxes lined up about 8 feet apart.', 'Begin facing the first box with one leg slightly behind the other.', 'Drive off the back leg, attempting to gain as much height with the hips as possible.', 'Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box.', 'Then, step to the next box and repeat.']::text[],
