),
(
  '24ed5b78-71f4-56cb-9a69-6c2c26926a48',
  'bretzel stretch',
  'Bretzel stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['How to Perform the Bretzel Stretch', '1. **Starting Position:** Lie on your back on a flat surface, such as a mat. Bend your knees and place your feet flat on the ground.', '2. **Leg Positioning:** Lift your right leg and cross it over your left leg, placing your right foot on the outside of your left knee. Your left leg should remain flat on the ground.', '3. **Arm Positioning:** Extend your left arm out to the side at shoulder height, keeping it straight. Use your right hand to gently pull your right knee towards the floor on the left side of your body.', '4. **Stretching:** As you pull your knee down, try to keep your left shoulder flat on the ground. You should feel a stretch in your hip, lower back, and possibly your chest.', '5. **Hold the Position:** Maintain this position for 20-30 seconds, breathing deeply and relaxing into the stretch. Switch sides and repeat the process.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'mountain.potato'
),
