  ARRAY['Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Step:2 Brace your trunk and lift your right foot off the ground, bringing your right knee toward your left elbow.', 'Step:3 Brace the trunk lightly before moving a limb.', 'Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.', 'Step:5 Keep the pelvis from rocking as the arm or leg moves.', 'Step:6 Reset your posture before changing sides or beginning the next rep.']::text[],
