  ARRAY['Step:1 Take a seat on the floor with your legs extended in front of you.', 'Step:2 Bend your knees and bring the soles of your feet together, letting your knees to fall out to the sides.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
