  'cable alternate triceps extension',
  'triceps',
  'cable',
  'triceps',
  ARRAY['deltoids']::text[],
  ARRAY['Step:1 Face the cable machine from a stable stance with feet about shoulder width.', 'Step:2 Take hold of the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.', 'Step:3 Set the upper arms in place before extending the elbows.', 'Step:4 Keep the upper arms steady and extend through the elbows to move the weight.', 'Step:5 Finish one side''s motion before the other side takes over.', 'Step:6 Bend the elbows slowly to return to the start of the next rep, switch sides when the set calls for it.']::text[],
