  'hamstrings',
  ARRAY['glutes', 'calves']::text[],
  ARRAY['Step:1 Set the cable machine so that the ankle attachment is at the lowest setting.', 'Step:2 Position yourself face down on the bench with your legs straight and the ankle attachment secured to your ankles.', 'Step:3 Line the knees up with the machine or bench edge before starting the curl.', 'Step:4 Bend your knees to draw the pad toward you without lifting your hips from the support.', 'Step:5 Keep the hips still while the knees bend.', 'Step:6 Return along the same path at a controlled pace.']::text[],
