  ARRAY['Step:1 Set the cable pulley to a high position and attach a straight bar.', 'Step:2 Sit facing the cable machine with your feet planted and your knees soft.', 'Step:3 Sit tall and set the shoulders before drawing the handle down.', 'Step:4 Pull the handle down by driving your elbows toward your ribs, keep your torso steady.', 'Step:5 Pull with the elbows rather than leaning far back to move the handle.', 'Step:6 Let the handle rise steadily until the arms are long, then reset the shoulders.']::text[],
