  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['### **Execution**', '1. **Start position:**', '* Arms extended out to your sides in a “Y” shape.', '* Feel a stretch in your chest (slight bend in elbows — don’t lock them).', '2. **Movement:**', '* Bring your hands **downward and together** in front of your **lower chest or upper abs**, in a smooth arc motion.', '* **Squeeze your chest** hard at the bottom for 1–2 seconds.', '3. **Return:**', '* Slowly raise your arms back up along the same path until you feel a good stretch in your chest.', '* Maintain control — don’t let the weights pull you back too quickly.']::text[],
