  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Step:1 Set the cable machine so that the preacher curl pad is at chest height.', 'Step:2 Take a seat on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with palms facing up.', 'Step:3 Set the working upper arm against the preacher pad and leave the elbow free to bend.', 'Step:4 Curl the weight while your upper arms stay in contact with the pad.', 'Step:5 Keep the torso quiet and let the elbow bend lift the weight.', 'Step:6 Lower until the elbows are nearly straight, keeping the upper arms still.']::text[],
