(
  '698472d8-3117-5372-8186-6cb9ba8eaf93',
  'around cable press',
  'Cable Press Around',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Set the cable pulley at chest height and attach a D-handle bar. Grab', 'the handle with a neutral grip and hold it next to your chest with your', 'elbow fully flexed and tight to your side. Turn away from the pulley so', 'your torso is at 45 degrees.', 'Hold the other side of the functional trainer with your corresponding hand. Assume a staggered stance for better balance.', 'While keeping your chest proud, extend your elbow at 45 degrees', 'across your midline while keeping your arm parallel to the floor. Stop', 'shy of lockout and contract your chest at the top of the range of motion', '(ROM).']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Expenses7000'
