(
  'aa099e7e-f37d-5c47-b978-d068c1887fb5',
  'cable press stabilityball',
  'cable press on exercise ball',
  'chest',
  'cable',
  'pectorals',
  ARRAY['deltoids', 'triceps']::text[],
  ARRAY['Step:1 Take a seat on an exercise ball with your feet planted and your knees at a 90-degree angle.', 'Step:2 Take hold of the cable handles at chest height with your palms facing down and your elbows bent.', 'Step:3 Brace the torso and align the wrists with the forearms.', 'Step:4 Press the weight or handles away while keeping your trunk braced.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Lower the weight to its starting height under control before pressing again.']::text[],
