(
  '6d8273ec-3ad3-5cb5-a3de-92cbf8618660',
  'cable pull through',
  'Cable pull through',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The **Cable Pull Through** is a lower-body exercise that targets the glutes and hamstrings using a "hip hinge" motion. To perform it, attach a rope to the lowest pulley setting, face away from the machine with the rope between your legs, and step forward to create tension. Keeping your back flat and knees slightly soft, push your hips backward as if trying to close a door behind you until you feel a deep stretch in your hamstrings.', 'To finish the rep, explosively drive your hips forward to return to a standing position, squeezing your glutes hard at the top. It is vital to remember that this is **not a squat**, your knees should not bend deeply, and your arms should remain straight and relaxed, acting only as hooks for the rope. This movement provides constant tension on the glutes while placing less stress on the lower back than a traditional deadlift.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'manuher89'
),
(
  'a5acec78-dbd1-59f6-bca2-7b3b733d8637',
  'cable pull rope through',
  'cable pull through (with rope)',
  'legs',
  'cable',
  'glutes',
  ARRAY['hamstrings', 'erector spinae']::text[],
  ARRAY['Step:1 Stand facing away from the low pulley with the rope passing between your legs.', 'Step:2 Take hold of the rope attachment with both hands and step forward, creating tension in the cable.', 'Step:3 Unlock the knees and brace the abdomen before moving the hips back.', 'Step:4 Push the hips back while keeping the load close and the spine steady.', 'Step:5 Keep the weight close to the legs and stop when the back would begin to round.', 'Step:6 Drive the hips forward to stand tall without leaning back at the top.']::text[],
  'https://static.exercisedb.dev/media/OM46QHm.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
