  ARRAY['Step:1 Take a seat on the rowing machine with your feet flat on the footrests and knees soft.', 'Step:2 Hold the cable ropes with palms facing down, palms facing each other.', 'Step:3 Set the torso and allow the arms to reach forward without rounding excessively.', 'Step:4 Draw your elbows back and bring the handle or weight toward your torso.', 'Step:5 Bring the elbows back without jerking the torso.', 'Step:6 Reach the arms forward again without letting the torso lurch.']::text[],
