(
  '3651d5bf-cd4d-545e-a7a0-705b0ebaf4ff',
  'cable russian twists',
  'Cable Russian Twists',
  'core',
  'cable',
  'abdominals',
  '{}'::text[],
  ARRAY['Connect a standard handle attachment, and position the cable to a middle pulley position.', 'Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable.', 'Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are.', 'Keep your hips elevated and abs engaged. Rotate your torso away from the pulley for a full-quarter rotation. Your body should be flat from head to knees.', 'Pause for a moment and in a slow and controlled manner reset to the starting position. You should still have side tension on the cable in the resting position.', 'Repeat the same movement to failure.', 'Then, reposition and repeat the same series of movements on the opposite side.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Cable_Russian_Twists/0.jpg',
