(
  '0ebd60ff-97e9-5573-ac06-7789fcefb13a',
  'bands calf raise',
  'Calf Raises - With Bands',
  'other',
  'bands',
  'calves',
  '{}'::text[],
  ARRAY['Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides.', 'While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position.', 'Keeping the hands by your shoulder, stand up on your toes as you exhale and contract the calves hard at the top of the movement.', 'After a one second contraction, slowly go back down to the starting position.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Calf_Raises_-_With_Bands/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
