  ARRAY['Place yourself on the machine with your back firmly against the backrest, the feet are on the platform for calf raises. Check that the feet are half free and that you can completely stretch the calf muscles down.', 'With straight knees pull up your weight as much as you can. Go with a fluid movement down till the calves are completely stretched. Repeat.']::text[],
