  '38335d2c-1d73-5061-8fc3-de8bbfb39aac',
  'against calf stretch wall',
  'calf stretch with hands against wall',
  'legs',
  'bodyweight',
  'calves',
  ARRAY['hamstrings']::text[],
  ARRAY['Step:1 Face a wall with your feet about hip width.', 'Step:2 Set your hands against the wall at shoulder height.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease the heel down and shift until the calf stretches, keep the foot pointed ahead.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/m0tCHqc.gif',
