(
  'd2b41f27-0801-51e7-8b36-e1145b23205a',
  'calf rope stretch',
  'calf stretch with rope',
  'legs',
  'rope',
  'calves',
  ARRAY['hamstrings']::text[],
  ARRAY['Step:1 Face a wall or sturdy object with your feet about hip width.', 'Step:2 Take hold of the ends of the rope in each hand and place the middle of the rope around the ball of your right foot.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease the heel down and shift until the calf stretches, keep the foot pointed ahead.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
  'https://static.exercisedb.dev/media/1LVFcEn.gif',
