(
  '90af9e99-1d9b-521e-b69a-6d42cf80ef53',
  'bar cambered lying row',
  'cambered bar lying row',
  'back',
  'barbell',
  'upper back',
  ARRAY['biceps', 'forearms']::text[],
  ARRAY['Step:1 Prepare a barbell on the floor and Position yourself face down on a bench with your chest just off the edge.', 'Step:2 Reach down and grab the barbell with palms facing down, just beyond shoulder width.', 'Step:3 Set the torso and allow the arms to reach forward without rounding excessively.', 'Step:4 Draw your elbows back and bring the handle or weight toward your torso.', 'Step:5 Bring the elbows back without jerking the torso.', 'Step:6 Reach the arms forward again without letting the torso lurch.']::text[],
  'https://static.exercisedb.dev/media/R5swFnc.gif',
