(
  '53eabb9c-6264-58ef-9a2a-715e504c31e0',
  'captains chair leg raise straight',
  'Captains Chair Straight-Leg Raise',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Take a seat on the captain''s chair with your back against the backrest and your forearms resting on the arm pads.', 'Step:2 Hold your torso stable and your back straight.', 'Step:3 Brace the abdomen and keep the shoulders anchored to the support.', 'Step:4 Lift your legs by bracing your trunk and moving at the hips rather than swinging.', 'Step:5 Slow the legs before they pull the lower back out of position.', 'Step:6 Lower the legs slowly without swinging or losing your trunk position.']::text[],
  'https://static.exercisedb.dev/media/weoDEpH.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '918b13de-8810-57e4-b648-8aa599c8e2da',
  'car deadlift',
  'Car Deadlift',
  'legs',
  'other',
  'quadriceps',
  ARRAY['forearms', 'glutes', 'hamstrings', 'lower back', 'traps']::text[],
  ARRAY['This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs.', 'Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower your hips and flex the knees.', 'Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. As the weight comes up, pull your shoulder blades together as you drive your hips forward.', 'Lower the weight by bending at the hips and guiding it to the floor.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Deadlift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
