  'car drivers',
  'Car Drivers',
  'shoulders',
  'barbell',
  'shoulders',
  ARRAY['forearms']::text[],
  ARRAY['While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position.', 'Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side.', 'Reverse the motion, turning it all the way to the opposite side.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Car_Drivers/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
