  'adductors',
  ARRAY['abdominals', 'abductors', 'calves', 'glutes', 'hamstrings', 'quadriceps']::text[],
  ARRAY['Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position.', 'With your right foot, quick step behind and pull the knee up.', 'Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.']::text[],
