  'lats',
  ARRAY['abdominals', 'chest', 'shoulders']::text[],
  ARRAY['Begin standing while facing a wall or a partner.', 'Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward.', 'Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.']::text[],
