(
  '2dded1d6-3e43-58db-9637-db43cbe054ab',
  'chair dips',
  'Chair dips',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['**Starting position:**', 'Sit down on the front edge of a chair, back straight, hands holding the front edge. Still holding the edge of the chair, arms extended, lift your butt and walk forward slightly so that it is a few inches from the chair.', '**Steps:**', '1. Slowly lower your body, keeping the back straight, until your arms are at a right angle.', '2. Raise your body again to the initial position, arms extended.', '3. Repeat.']::text[],
  null,
