  ARRAY['deltoids']::text[],
  ARRAY['Step:1 Stand tall and set your feet about shoulder width.', 'Step:2 Reach your arms straight out in front of you at shoulder height.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
