  'bodyweight',
  'pectorals',
  ARRAY['triceps', 'deltoids']::text[],
  ARRAY['Step:1 Set yourself on parallel bars with your arms straight and your body straight.', 'Step:2 Before moving, lower your body by bending your elbows until your shoulders are below your elbows.', 'Step:3 Set the shoulders down and keep the elbows pointed mostly behind you.', 'Step:4 Bend the elbows to lower between the supports, stop at a comfortable shoulder depth.', 'Step:5 Choose a depth that lets the shoulders stay comfortable.', 'Step:6 Press through the hands to rise, then reset the shoulders before another rep.']::text[],
