  ARRAY['Step:1 Set the dip bars to a height that allows you to comfortably grip them.', 'Step:2 Stand between the bars and place your hands on each bar, just beyond shoulder width.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
