  ARRAY['1. Adjust the seat height so that the grips are parallel to your chest.', '2. Use your legs to push the foot forward pedal.', '3. Bring the handles to the start position.', '4. Keep your back in contact with the back pad, press outwards.', '5. Press the handles away from your chest and exhale.', '6. Allow the handles to come in gently until they reach your chest.', '7. Allow the handles to return to your chest as you inhale.']::text[],
