  ARRAY['Step:1 Take a seat on the stability ball with your feet planted and your back straight.', 'Step:2 Take hold of the exercise ball with both hands and extend your arms straight out in front of you.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Keep the ball steady and use the feet to manage your balance.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
