  ARRAY['Step:1 Stand and set your feet about shoulder width and your hands on your hips.', 'Step:2 Before moving, bend your knees slightly and lift your heels off the ground, balancing on the balls of your feet.', 'Step:3 Settle into the starting position and take an easy breath before moving deeper.', 'Step:4 Ease toward the stretch until you feel mild tension, keep breathing and avoid bouncing.', 'Step:5 Stay in a mild stretch rather than pulling farther with momentum.', 'Step:6 Hold the position with steady breathing, then release gently, repeat on the other side if needed.']::text[],
