),
(
  'a79afdd4-3c49-5714-aa57-a465b998ba03',
  'clean shrug',
  'Clean Shrug',
  'back',
  'barbell',
  'traps',
  ARRAY['forearms', 'shoulders']::text[],
  ARRAY['Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward.', 'Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.']::text[],
