  'ClimbMill',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The ClimbMill, also known as a stair climber, is a cardio-focused machine that simulates climbing stairs. It provides an effective way to improve endurance while strengthening the lower body. To use the machine, step onto the moving stairs, maintain an upright posture, and use the handrails for balance if needed. Adjust the speed and intensity to match your fitness level. This exercise helps improve cardiovascular health, burns calories, and enhances lower body muscle endurance.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'hpmbala@gmail.com'
),
(
  '57e09a61-a691-55e2-a8f9-7e87ca7b91fd',
  'clock pushup',
  'clock push-up',
  'chest',
  'bodyweight',
  'pectorals',
  ARRAY['triceps', 'deltoids', 'core']::text[],
  ARRAY['Step:1 Begin in a high plank position with your hands directly under your shoulders and your body in a straight line.', 'Step:2 Lower your body toward the ground by bending your elbows, keeping them close to your sides.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
  'https://static.exercisedb.dev/media/CMAxnsG.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '813dfa47-db83-57cc-ab31-ab9c8c7c2fe0',
  'circles clockwise neck',
  'Clockwise neck circles',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Starting position:', 'Start sitting or standing. Drop your head down, bringing your chin toward your chest, but not pushing.', 'Steps:', 'In a slower fluid motion and with your head relaxed and not pushing in any direction:', '1. lean toward your right shoulder.', '2. then bring your head back, facing up.', '3. then lean toward your left shoulder.4.and back toward the starting position.', 'Keep repeating this as part of one slower fluid motion.']::text[],
  null,
  null,
  'wger',
