(
  'd8110691-a7ce-521e-91c9-0ad05390475d',
  'chinup closegrip',
  'Close-Grip Chin-Up',
  'back',
  'bodyweight',
  'latissimus dorsi',
  ARRAY['biceps', 'forearms']::text[],
  ARRAY['Step:1 Take hold of the pull-up bar with your palms facing toward you and your hands about shoulder width.', 'Step:2 Suspend yourself from the bar with your arms straight and your feet off the ground.', 'Step:3 Begin from a controlled hang with the shoulders active rather than slack.', 'Step:4 Pull your elbows down and bring your upper chest toward the bar without kicking your legs.', 'Step:5 Avoid swinging the legs to clear the bar.', 'Step:6 Lower to long arms without dropping suddenly from the top.']::text[],
  'https://static.exercisedb.dev/media/VnfUNW7.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'eb8eb61c-f738-5992-861e-f639fbf12199',
  'band closegrip curl ezbar',
  'Close-Grip EZ-Bar Curl with Band',
  'biceps',
  'e-z curl bar',
  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position.', 'While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted.', 'Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps hard.', 'Slowly begin to bring the bar back to starting position as your breathe in.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Curl_with_Band/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '115d989b-3c0b-50c2-85c3-d8a784c8fb7e',
  'closegrip ezbar press',
  'Close-Grip EZ-Bar Press',
  'triceps',
  'e-z curl bar',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Lie on a flat bench with an EZ bar loaded to an appropriate weight.', 'Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale.', 'Repeat.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_EZ-Bar_Press/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'c5410560-22b4-5bc2-9858-8bdc6e71918b',
  'closegrip front lat pulldown',
  'Close-Grip Front Lat Pulldown',
  'back',
  'cable',
  'lats',
  ARRAY['biceps', 'middle back', 'shoulders']::text[],
  ARRAY['Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.', 'Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.', 'As you have both arms extended in front of you - while holding the bar at the chosen grip width - bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.', 'As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary (only the arms should move). The forearms should do no other work except for holding the bar, therefore do not try to pull the bar down using the forearms.', 'After a second in the contracted position, while squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.', '6. Repeat this motion for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Close-Grip_Front_Lat_Pulldown/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
