  '9ff26bf9-cfe4-5f9c-b687-1d837c9ddfb7',
  'cobra stretch',
  'Cobra Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The Cobra Stretch is a back extension exercise that helps improve spinal flexibility and relieve lower back tension. To perform, lie face down on the floor with your hands placed under your shoulders. Press your palms into the floor and lift your chest while keeping your hips on the ground. Keep your elbows slightly bent and your shoulders relaxed. Hold the stretch for a few seconds, then slowly lower yourself back down. This exercise is beneficial for improving posture and reducing lower back stiffness.']::text[],
