  'legs',
  'other',
  'quadriceps',
  ARRAY['abdominals', 'biceps', 'calves', 'forearms', 'lower back', 'shoulders', 'traps']::text[],
  ARRAY['With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms.', 'Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.']::text[],
