  'Couch Stretch',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Stand facing away from a bench, couch or similar-height object.', '2. Extend one leg backwards, resting your foot "laces-down" on the edge of the bench.', '3. Lower yourself until your rear knee is on the floor and you are in a lunge position, with your torso hanging forwards slightly.', '4. Brace your core, tense your rear glute, and straighten up your torso to vertical, under control. Relax and repeat.', 'Repeat for the other leg, too.']::text[],
