  ARRAY['Step:1 Begin by sitting on the ground with your knees bent and feet planted.', 'Step:2 Set your hands behind you, fingers pointing toward your feet, and lift your hips off the ground.', 'Step:3 Soften the knees and let the hips start the fold.', 'Step:4 Fold forward from the hips and let your hands travel toward your feet without forcing the reach.', 'Step:5 Keep the movement controlled throughout the range.', 'Step:6 Hold briefly at a comfortable depth, then rise by extending the hips.']::text[],
