  'biceps',
  ARRAY['forearms']::text[],
  ARRAY['Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in.', 'While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second.', 'Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm.', 'Continue alternating in this fashion until the recommended amount of repetitions is performed for each arm.']::text[],
