(
  '59b592c1-76e6-52ed-a675-cc9d14264d47',
  'crucifix',
  'Crucifix',
  'shoulders',
  'other',
  'shoulders',
  ARRAY['forearms']::text[],
  ARRAY['In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different.', 'Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be heavy enough that you fail in 30-60 seconds.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crucifix/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'd281e682-0200-5213-902f-4c239f9eb375',
  'crunch legs stabilityball',
  'Crunch - Legs On Exercise Ball',
  'core',
  'body only',
  'abdominals',
  '{}'::text[],
  ARRAY['Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle.', 'Place your feet three to four inches apart and point your toes inward so they touch.', 'Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head.', 'Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position.', 'Begin to roll your shoulders off the floor and continue to push down as hard as you can with your lower back. Your shoulders should come up off the floor only about four inches, and your lower back should remain on the floor. Breathe out as you execute this portion of the movement. Squeeze your abdominals hard at the top of the contraction and hold for a second. Tip: Focus on a slow, controlled movement. Refrain from using momentum at any time.', 'Slowly go back down to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Crunch_-_Legs_On_Exercise_Ball/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
