(
  '2f204a4a-d9d5-5437-a38e-605726b8dbb5',
  'barra con curl de eca mu',
  'Curl De Muñeca Con Barra',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['This is a variation of the flat bench press designed to emphasize the clavicular head of the pectoralis major (the upper portion). By tilting the torso, the angle of the push changes, shifting more tension to the upper chest and shoulders, which helps achieve a more aesthetic, balanced, and three-dimensional development of the torso.', '1. Starting Position: Grip a bar with an overhand grip (palms facing up) at a width similar to your shoulders.', '2. Position on the Bench: Kneel in front of a flat bench and rest the backs of your forearms on it. Your wrists and hands should extend slightly beyond the edge of the bench to allow for a full range of motion.', '3. Eccentric Phase (Lowering): Lower the bar in a controlled manner by extending your wrists toward the floor. At the bottom of the movement, slightly spread your fingers to let the bar roll down a bit, maximizing the stretch.', '4. Concentric Phase (Lift): First, close your fingers to secure the bar, then flex your wrists upward explosively but in a controlled manner, bringing the bar as high as possible. Strongly contract your forearms at the top position for one second.', '5. Form: Keep your forearms firmly pressed against the bench throughout the exercise, only your wrists and fingers should move.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'xWan'
),
