  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors', 'erector spinae']::text[],
  ARRAY['Step:1 Settle onto your back with your arms extended toward the ceiling.', 'Step:2 Before moving, bend your knees and lift your legs off the ground, creating a 90-degree angle at your hips and knees.', 'Step:3 Brace the trunk lightly before moving a limb.', 'Step:4 Move the working arm or leg while keeping the trunk steady and the breathing even.', 'Step:5 Keep the pelvis from rocking as the arm or leg moves.', 'Step:6 Reset your posture before changing sides or beginning the next rep.']::text[],
