(
  '531922ef-6fc5-554f-87bd-716da93698e2',
  'bands deadlift',
  'Deadlift with Bands',
  'back',
  'barbell',
  'lower back',
  ARRAY['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[],
  ARRAY['To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Bands/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '2c728e6e-97d5-509e-b0e0-e57dafa42f97',
  'chains deadlift',
  'Deadlift with Chains',
  'back',
  'barbell',
  'lower back',
  ARRAY['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[],
  ARRAY['You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift.', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.', 'Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deadlift_with_Chains/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '2bd86f8c-9e48-5e56-8da7-daa8ace1e6fb',
  'deadlift',
  'Deadlifts',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Stand firmly, with your feet slightly more than shoulder wide apart. Stand directly behind the bar where it should barely touch your shin, your feet pointing a bit out. Bend down with a straight back, the knees also pointing somewhat out. Grab the bar with a shoulder wide grip, one overhand, one underhand (mixed grip).', 'Pull the weight up. At the highest point make a slight hollow back and pull the bar back. Hold 1 or 2 seconds that position. Go down, making sure the back is not bent. Once down you can either go back again as soon as the weights touch the floor, or make a pause, depending on the weight.']::text[],
  null,
