  'wger.de'
),
(
  '357965cb-6d1f-5e32-b0d5-1d097c8792ff',
  'bench decline leg raise',
  'Decline Bench Leg Raise',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['- **Setup**: Lie on a decline bench with your head at the top and grip the handles.', '- **The Start**: Extend legs fully, keeping them slightly elevated to engage your core.', '- **The Lift**: Raise your legs toward the ceiling using your abs, not momentum.', '- **The Squeeze**: Pause and contract your lower abdominals at the top.', '- **The Return**: Lower your legs slowly to the starting position with control.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'nishant0712'
),
(
  '72da23f3-2ab9-5e21-889e-35f44ca9e58d',
  'bench closegrip crusher decline skull',
  'Decline Close-Grip Bench To Skull Crusher',
  'triceps',
  'barbell',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.', 'Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement.', 'Using the triceps to push the bar back up, press it back to the starting position as you exhale.', 'As you breathe in and you keep the upper arms stationary, bring the bar down slowly by moving your forearms in a semicircular motion towards you until you feel the bar slightly touch your forehead. Breathe in as you perform this portion of the movement.', 'Lift the bar back to the starting position by contracting the triceps and exhaling.', 'Repeat steps 3-6 until the recommended amount of repetitions is performed.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '82030109-2972-5206-8101-41841e6920ac',
