  'abdominals',
  ARRAY['hip flexors']::text[],
  ARRAY['Step:1 Settle onto a decline bench with your feet secured and your knees bent at a 90-degree angle.', 'Step:2 Set your hands behind your head or across your chest.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
  'https://static.exercisedb.dev/media/9Ap7miY.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  'f991f213-5eb9-57f0-af03-2bcec53a2870',
  'decline dumbbell flyes',
  'Decline Dumbbell Flyes',
  'chest',
  'dumbbell',
  'chest',
  '{}'::text[],
  ARRAY['Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.', 'Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position.', 'With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary, the movement should only occur at the shoulder joint.', 'Return your arms back to the starting position as you squeeze your chest muscles and breathe out. Tip: Make sure to use the same arc of motion used to lower the weights.', 'Hold for a second at the contracted position and repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Dumbbell_Flyes/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '05e1296f-b279-5bbf-96ce-b8b99a7dfe06',
  'crunch decline oblique',
  'Decline Oblique Crunch',
  'core',
  'body only',
  'abdominals',
  '{}'::text[],
  ARRAY['Secure your legs at the end of the decline bench and slowly lay down on the bench.', 'Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor.', 'Put one hand beside your head and the other on your thigh. This will be your starting position.', 'Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a second. Tip: Focus on keeping your abs tight and keeping the movement slow and controlled.', 'Lower your body back down slowly to the starting position as you inhale.', 'After completing one set on the right for the recommended amount of repetitions, switch to your left side. Tip: Focus on really twisting your torso and feeling the contraction when you are in the up position.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Oblique_Crunch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  '53db830c-1615-5e62-a5c6-2f74240e9755',
  'decline pushup',
  'decline push-up',
  'chest',
  'bodyweight',
  'pectorals',
  ARRAY['triceps', 'deltoids']::text[],
  ARRAY['Step:1 Set your hands on the ground just beyond shoulder width, with your feet elevated on a stable surface.', 'Step:2 Hold your body in a straight line from head to toe, engaging your core muscles.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
  'https://static.exercisedb.dev/media/i5cEhka.gif',
  'gif',
  'exercisedb',
  'AscendAPI ExerciseDB free tier, non-commercial',
  'AscendAPI'
),
(
  '5214ae00-8250-5559-bd4b-0f8be3a46909',
  'crunch decline reverse',
  'Decline Reverse Crunch',
  'core',
  'body only',
  'abdominals',
  '{}'::text[],
  ARRAY['Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position.', 'Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position.', 'While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of this movement your knees will be touching your chest.', 'Hold the contraction for a second and move your legs back to the starting position while inhaling.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Decline_Reverse_Crunch/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
