  'decline sit up',
  'decline sit-up',
  'core',
  'bodyweight',
  'abdominals',
  ARRAY['hip flexors', 'erector spinae']::text[],
  ARRAY['Step:1 Settle onto a decline bench with your feet secured and your knees bent.', 'Step:2 Set your hands behind your head or across your chest.', 'Step:3 Set the pelvis and keep the neck relaxed before curling upward.', 'Step:4 Curl your rib cage toward your pelvis, letting the abdominals move the torso.', 'Step:5 Leave a little space between the chin and chest, keep the movement in the torso.', 'Step:6 Lower the shoulders or torso with control before the next curl.']::text[],
