),
(
  'c2fd1575-d7ee-5657-9728-bab366614e7b',
  'deadlift deficit',
  'Deficit Deadlift',
  'back',
  'barbell',
  'lower back',
  ARRAY['forearms', 'glutes', 'hamstrings', 'middle back', 'quadriceps', 'traps']::text[],
  ARRAY['Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets.', 'With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knees, aggressively pull the bar back, pulling your shoulder blades together as you drive your hips forward into the bar.', 'Lower the bar by bending at the hips and guiding it to the floor.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Deficit_Deadlift/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
