(
  'abc14dcb-1f3b-58c2-8dce-f744c0f095cb',
  'depth jump leap',
  'Depth Jump Leap',
  'legs',
  'other',
  'quadriceps',
  ARRAY['abductors', 'adductors', 'calves', 'glutes', 'hamstrings']::text[],
  ARRAY['For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high.', 'Stand on one of the two boxes with arms at the sides, feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer.', 'Begin by dropping off the initial box, landing and simultaneously taking off with both feet.', 'Rebound by driving upward and outward as intensely as possible, using the arms and full extension of the body to jump onto the higher box. Again, allow the legs to absorb the impact.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Depth_Jump_Leap/0.jpg',
