),
(
  'ffd5d629-e95a-5d8a-8c84-df438ad8a96a',
  'devils press',
  'Devil’s Press',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['The Devil’s Press is a hybrid movement combining a dumbbell burpee and a double dumbbell snatch. It’s a full-body, high-intensity exercise that develops strength, power, and metabolic conditioning.', '1. Start with a dumbbell in each hand and perform a burpee, letting your chest touch the ground while holding the dumbbells.', '2. Explosively jump your feet forward and swing the dumbbells between your legs.', '3. Drive the dumbbells overhead in one continuous motion, locking out your arms.', '4. Lower the dumbbells with control to return to the starting position and repeat']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Settebello'
),
(
  '66f8cc22-0b1e-5e5f-ab1b-b7ced642b52e',
  'diagonal press shoulder',
  'Diagonal Shoulder Press',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['You sit at the bench press device, back slightly tilted to the back. The bar should be about 20 cm in front of you. Then you push the bar and take it back again, as you would with a bench press.', 'In this position you strain your chest muscles a lot less, which is nice if you want to train, but your chest hasn''t recovered yet.']::text[],
