  ARRAY['Step:1 Begin in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.', 'Step:2 Hold your body in a straight line from head to toe, engaging your core and glutes.', 'Step:3 Brace the abdomen and glutes so the shoulders, hips and ankles move together.', 'Step:4 Bend your elbows to lower your chest while keeping your body in one line.', 'Step:5 Keep the head in line with the spine as the elbows bend.', 'Step:6 Press back to straight arms, keeping the body line intact.']::text[],
