  '651c17ac-7474-5297-b086-38b531771268',
  'dip machine',
  'Dip Machine',
  'triceps',
  'machine',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['Sit securely in a dip machine, select the weight and firmly grasp the handles.', 'Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle.', 'As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle.', 'Now slowly let your arms come back up to the starting position as you inhale.', 'Repeat for the recommended amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dip_Machine/0.jpg',
  'image',
