(
  '8a9e1fa0-979d-5783-af55-797913a4f7a0',
  'dips',
  'Dips',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['A dip is an upper-body strength exercise. Narrow, shoulder-width dips primarily train the triceps, with major synergists being the anterior deltoid, the pectoralis muscles (sternal, clavicular, and minor), and the rhomboid muscles of the back (in that order).[1] Wide arm training places additional emphasis on the pectoral muscles, similar in respect to the way a wide grip bench press would focus more on the pectorals and less on the triceps.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'BFad07'
),
(
  '48eae10f-e502-5a72-ab84-eb332ab3a23a',
  'chest dips',
  'Dips - Chest Version',
  'chest',
  'other',
  'chest',
  ARRAY['shoulders', 'triceps']::text[],
  ARRAY['For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars.', 'While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest.', 'Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of the movement for a second.', 'Repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Chest_Version/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
(
  'a8012f5f-e291-569b-a02d-4e332ff82e38',
  'dips triceps',
  'Dips - Triceps Version',
  'triceps',
  'body only',
  'triceps',
  ARRAY['chest', 'shoulders']::text[],
  ARRAY['To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars.', 'Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm.', 'Then, exhale and push your torso back up using your triceps to bring your body back to the starting position.', 'Repeat the movement for the prescribed amount of repetitions.']::text[],
  'https://raw.githubusercontent.com/yuhonas/free-exercise-db/main/exercises/Dips_-_Triceps_Version/0.jpg',
  'image',
  'public_domain',
  'Unlicense',
  null
),
