  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['1. Starting', 'position for this rope pushdown is standing facing a cable machine with', 'the handles of a rope attachment in both hands and feet shoulder width', 'apart.', '2. Hinge', 'forward slightly at the hips maintaining an upright chest and bring the', 'shoulders and elbows behind the body so that when you push down on the', 'cable attachments, you can get a fully contracted triceps long head.', '3. Drag', 'the cable machine rope attachment as close to the body as possible and', 'straighten your elbows until lockout.']::text[],
