(
  '3200e8d2-fa20-53ff-bf2a-0dda384f5d24',
  'curl drop',
  'Drop Curl',
  'other',
  '',
  '',
  '{}'::text[],
  ARRAY['Drop curls in a modified position at a slow pace effectively engage the brachialis for arm width.', 'Starting position is with both arms in a slight angle towards each other at chest height with a dumbbell in each hand. Lower one dumbbell close to full extended arm position slowly and in a controlled manner during the first half of the curl, then curl it back up to starting position, while the other dumbbell stays at its starting position. Now lower the other dumbbell down. This keeps tension on the brachialis. As we pass the 90deg mark on our way down, the biceps will take over the work.']::text[],
  null,
  null,
  'wger',
  'CC-BY-SA-4.0',
  'Moffi'
),
