  '',
  '{}'::text[],
  ARRAY['1. Starting position is standing', 'with feet shoulder width apart.', '2. Hands should take an underhand', 'or supinated grip on the dumbbells holding them with hands shoulder', 'width apart.', '3. Keeping elbows tucked into your', 'sides throughout the entire movement, use momentum to curl the dumbbells,', 'squeezing your biceps at the top of the movement.', '4. Slowly lower to return to the', 'starting position. Keep the core tight throughout the exercise.', 'Cheating', 'through the concentric curling portion of this challenging exercise gives us a', 'great opportunity to increase time under tension and create eccentric overload', 'with heavier weight when we lower.']::text[],
